package com.bank.trend.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Longest strictly increasing subsequence via per-index best lengths.
public class BalanceTrendService {
    private static final Logger log = Logger.getLogger(BalanceTrendService.class.getName());

    public int longestRisingStreak(int[] balances) {
        int n = balances.length;
        if (n == 0) return 0;
        int[] len = new int[n];                     // len[i] = best rising run ending at i
        Arrays.fill(len, 1);                        // each element alone has length 1
        int best = 1;
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (balances[j] < balances[i])       // strictly rising
                    len[i] = Math.max(len[i], len[j] + 1);
            }
            best = Math.max(best, len[i]);
        }
        final int r = best;
        log.info(() -> "Longest rising balance streak = " + r);
        return best;
    }
}
