package com.bank.trend;

import com.bank.trend.service.BalanceTrendService;
import java.util.logging.Logger;

public class BalanceTrendApplication {
    private static final Logger log = Logger.getLogger(BalanceTrendApplication.class.getName());

    public static void main(String[] args) {
        BalanceTrendService service = new BalanceTrendService();
        int[] balances = {2, 9, 3, 6, 5, 8};
        int streak = service.longestRisingStreak(balances);
        log.info("Longest strictly rising balance streak length is " + streak);
    }
}
